mapper.update:
update iip_points_account
member_id = #{memberId}, total_points = #{totalPoints}, available_points = #{availablePoints}, used_points = #{usedPoints}, expired_points = #{expiredPoints}, version = #{version}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where account_id = #{accountId}

update iip_points_account
set available_points = available_points - #{points},
    used_points = used_points + #{points},
    update_time = sysdate()
where member_id = #{memberId}
  and available_points >= #{points}

update iip_points_account
set available_points = available_points + #{points},
    used_points = used_points - #{points},
    update_time = sysdate()
where member_id = #{memberId}
  and used_points >= #{points}

update iip_points_account
set available_points = available_points - #{points},
    expired_points = expired_points + #{points},
    update_time = sysdate()
where member_id = #{memberId}
  and available_points >= #{points}
